using System;using System.IO;using System.Text;using System.Security.Cryptography;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;
namespace IdleIntelligence.Tests {
 public sealed class SaveJsonValidationTests {
 [Test]public void StreamingValidationMatchesTreeContractIncludingLexicalErrorPrecedence(){var codec=new UnitySaveCodec();string raw=codec.Encode(StateData.From(Game.New(1000000)));string[] cases={raw,"null","{}","[]","true","42","\"text\"",raw.Insert(1,"\"futureProgress\":42,"),raw.Insert(1,"\"futureProgress\":{\"x\":01},"),raw.Insert(1,"\"futureProgress\":{\"x\":1,\"x\":2},"),raw.Replace("\"quality\":0","\"quality\":0.5"),raw.Replace("\"quality\":0","\"quality\":\"0\""),raw.Replace("\"quality\":0","\"quality\":false"),raw.Replace("\"quality\":0","\"quality\":[]"),raw.Replace("\"quality\":0","\"quality\":{}"),raw.Replace("\"quality\":0","\"quality\":null"),raw.Replace("\"quality\":0","\"quality\":0,\"quality\":1"),raw.Replace("\"effects\":true,",""),raw+"null",raw.Replace("\"quality\":0","\"quality\":1e400")};foreach(string json in cases){Type tree=null,stream=null;try{SaveJsonValidation.ValidateValue(SaveJsonValidation.Parse(json),typeof(StateData),true);}catch(Exception e){tree=e.GetType();}try{SaveJsonValidation.Validate(json,typeof(StateData),true);}catch(Exception e){stream=e.GetType();}Assert.That(stream,Is.EqualTo(tree),"Contract divergence for "+json.Substring(0,Math.Min(90,json.Length)));}}
 [Test]public void PlainAndEscapedStringsKeepIdenticalUnicodeValidation(){Assert.That(SaveJsonValidation.Parse("\"Mira Voss\"").Text,Is.EqualTo("Mira Voss"));Assert.That(SaveJsonValidation.Parse("\"é 🚀\"").Text,Is.EqualTo("é 🚀"));Assert.That(SaveJsonValidation.Parse("\"line\\nquote\\\"\\uD83D\\uDE80\"").Text,Is.EqualTo("line\nquote\"🚀"));Assert.Throws<FormatException>(()=>SaveJsonValidation.Parse("\""+new string((char)0xD800,1)+"\""));Assert.Throws<FormatException>(()=>SaveJsonValidation.Parse("\""+new string((char)0xDC00,1)+"\""));Assert.Throws<FormatException>(()=>SaveJsonValidation.Parse("\"line\nraw\""));}
 [Test]public void OriginalUnityPayloadPassesWithoutDroppingFields(){var codec=new UnitySaveCodec();var state=Game.New(1000000);string raw=codec.Encode(StateData.From(state));var decoded=codec.Decode(raw,AtomicSaveStore.Version);Game.Validate(decoded.ToState());Assert.That(codec.Encode(decoded),Is.EqualTo(raw));}
 [TestCase("{\"x\":1,\"x\":2}")][TestCase("{\"x\":01}")][TestCase("[true,]")][TestCase("{\"x\":1e400}")][TestCase("{\"x\":1}null")][TestCase("{\"x\":\"\\uD800\"}")]
 public void InvalidRawJsonCannotBeCoerced(string raw){Assert.Throws<FormatException>(()=>SaveJsonValidation.Parse(raw));}
 [TestCase(true)][TestCase(false)]public void UnknownAndCoercedExternalReplacementNeverOverwritesOriginal(bool unknown){string dir=Path.Combine(Path.GetTempPath(),"unity-raw-original-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{string path=Path.Combine(dir,"save.json");var codec=new UnitySaveCodec();var store=new AtomicSaveStore(path,codec);var load=store.Load(1000000);store.Save(load.State);string payload=codec.Encode(StateData.From(load.State));payload=unknown?payload.Replace("\"settings\":{","\"settings\":{\"futurePreference\":true,"):payload.Replace("\"quality\":0","\"quality\":0.25");string hash;using(var sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(payload))).Replace("-","").ToLowerInvariant();string raw=codec.EncodeEnvelope(new SaveEnvelope{format=AtomicSaveStore.Format,version=AtomicSaveStore.Version,payload=payload,sha256=hash});File.WriteAllText(path,raw);var result=new AtomicSaveStore(path,codec).Load(1000000);Assert.That(result.Writable,Is.False);Assert.That(File.ReadAllText(path),Is.EqualTo(raw));Assert.Catch(()=>store.Save(load.State));Assert.That(File.ReadAllText(path),Is.EqualTo(raw));Assert.That(File.Exists(path+".pending"),Is.False);}finally{Directory.Delete(dir,true);}}
 [Test]public void UnknownFieldsDuplicateAndNumericCoercionsAreRejected(){var codec=new UnitySaveCodec();string raw=codec.Encode(StateData.From(Game.New(1000000)));Assert.Throws<NotSupportedException>(()=>codec.Decode(raw.Insert(1,"\"futureProgress\":42,"),16));Assert.Throws<FormatException>(()=>codec.Decode(raw.Replace("\"quality\":0","\"quality\":0.5"),16));Assert.Throws<FormatException>(()=>codec.Decode(raw.Replace("\"quality\":0","\"quality\":\"0\""),16));Assert.Throws<FormatException>(()=>codec.Decode(raw.Replace("\"effects\":true,",""),16));Assert.Throws<FormatException>(()=>codec.Decode(raw.Replace("\"quality\":0","\"quality\":0,\"quality\":0"),16));}
 }
}
